import{_ as e,c as a,o as r,a3 as o}from"./chunks/framework.MI-M1z4O.js";const y=JSON.parse('{"title":"エンジニアリング研究アーカイブ (Study)","description":"SyncSeriesの主要技術スタックであるPlaywright、Vision-LLM、MCP、ハイブリッドRAG、高性能Javaランタイムに関する深層技術研究およびアーキテクチャ分析資料集です。","frontmatter":{"title":"エンジニアリング研究アーカイブ (Study)","description":"SyncSeriesの主要技術スタックであるPlaywright、Vision-LLM、MCP、ハイブリッドRAG、高性能Javaランタイムに関する深層技術研究およびアーキテクチャ分析資料集です。","head":[["meta",{"name":"keywords","content":"技術研究, Playwright CDP, Vision-LLM, 自己修復アルゴリズム, MCPオーケストレーション, ハイブリッドRAG, 仮想スレッド, AgentScope, 株式会社エムパシー"}],["meta",{"property":"og:title","content":"エンジニアリング研究アーカイブ | 株式会社エムパシー (Empasy)"}],["meta",{"property":"og:description","content":"実践的なエンジニアリング課題解決のための深層技術分析およびアーキテクチャ研究資料です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/study/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/study/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/study/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/study/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/study/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/study/"}]],"sort":1},"headers":[],"relativePath":"ja/study/index.md","filePath":"ja/study/index.md","lastUpdated":1795293539000}'),l={name:"ja/study/index.md"};function n(s,t,i,d,c,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="エンジニアリング研究アーカイブ-study" tabindex="-1">エンジニアリング研究アーカイブ (Study) <a class="header-anchor" href="#エンジニアリング研究アーカイブ-study" aria-label="Permalink to “エンジニアリング研究アーカイブ (Study)”">​</a></h1><p>本スペースは、株式会社エムパシー（Empasy）のSyncSeries（SyncETA、SyncVerse、SyncBoot、SyncCrawlなど）製品群の基盤となる主要技術スタックについて、実装原理や性能ベンチマーク、アーキテクチャ設計パターンを深く研究し記録する技術アーカイブです。</p><hr><h2 id="主要研究テーマの分類" tabindex="-1">主要研究テーマの分類 <a class="header-anchor" href="#主要研究テーマの分類" aria-label="Permalink to “主要研究テーマの分類”">​</a></h2><h3 id="_1-webブラウザ自動化-qaエンジニアリング" tabindex="-1">1. Webブラウザ自動化 &amp; QAエンジニアリング <a class="header-anchor" href="#_1-webブラウザ自動化-qaエンジニアリング" aria-label="Permalink to “1. Webブラウザ自動化 &amp; QAエンジニアリング”">​</a></h3><ul><li><strong><a href="./playwright-cdp-visual-regression">PlaywrightおよびCDPベースの視覚的回帰分析とDOM同期</a></strong>：Chrome DevTools Protocolを活用したレンダリングフレームキャプチャおよびネットワークアイドル状態の同期手法の分析。</li><li><strong><a href="./vision-llm-self-healing-algorithm">Vision-LLMベースのUI要素バウンディングボックス推論および自己修復（Self-Healing）アルゴリズム</a></strong>：画面の視覚的コンテキストと座標を活用し、クラス名の変更に対応する回帰テスト復旧パイプライン。</li></ul><h3 id="_2-分散エージェント-プロトコル" tabindex="-1">2. 分散エージェント &amp; プロトコル <a class="header-anchor" href="#_2-分散エージェント-プロトコル" aria-label="Permalink to “2. 分散エージェント &amp; プロトコル”">​</a></h3><ul><li><strong><a href="./mcp-jsonrpc-agent-orchestration">Model Context Protocol (MCP) JSON-RPC仕様分析とツールオーケストレーション</a></strong>：Claude/Playwright標準ツールインターフェースおよびエンタープライズセキュリティゲートウェイの設計パターン。</li><li><strong><a href="./springboot-virtual-threads-agentscope">Java 25仮想スレッドとAgentScopeベースの非同期メッセージング性能分析</a></strong>：Spring Boot環境におけるブロッキングI/Oの克服と、数万単位の同時エージェント通信処理ベンチマーク。</li></ul><h3 id="_3-aiモデル-ナレッジパイプライン" tabindex="-1">3. AIモデル &amp; ナレッジパイプライン <a class="header-anchor" href="#_3-aiモデル-ナレッジパイプライン" aria-label="Permalink to “3. AIモデル &amp; ナレッジパイプライン”">​</a></h3><ul><li><strong><a href="./hybrid-rag-dense-sparse-reranking">エンタープライズRAGアーキテクチャ：Sparse + Denseハイブリッド検索とCross-Encoderリランキング</a></strong>：ドメイン特化検索の精度向上のためのBM25と埋め込みベクトルの結合パイプライン。</li><li><strong><a href="./vision-llm-finetuning">Llama-3.2-Visionマルチモーダルモデル ファインチューニング実践</a></strong>：韓国語Web UI画面コンポーネント認識のためのデータセット構築およびLoRAチューニング。</li><li><strong><a href="./llm-finetuning-degradation-analysis">LLMファインチューニング後の性能劣化要因および解決策の分析</a></strong>：Catastrophic Forgettingの防止およびアライメントデータの補正研究。</li><li><strong><a href="./rag">RAGベースのナレッジ検索パイプライン構築</a></strong>：非構造化データのチャンキングおよびメタデータフィルタリング戦略。</li></ul><hr><h2 id="研究方法論および検証基準" tabindex="-1">研究方法論および検証基準 <a class="header-anchor" href="#研究方法論および検証基準" aria-label="Permalink to “研究方法論および検証基準”">​</a></h2><p>株式会社エムパシーのエンジニアリングチームは、すべての技術研究において以下の原則を遵守しています。</p><ol><li><strong>コードレベルの実証</strong>：理論的モデルにとどまらず、実際に実行可能なプロトタイプまたはベンチマークコードを作成して性能を検証します。</li><li><strong>定量的データの提示</strong>：レイテンシ、メモリ占有率、スループット（Throughput）、失敗率などの数値化された指標に基づいて技術採用の可否を決定します。</li><li><strong>商用安定性の検討</strong>：ネットワーク断絶、スレッド枯渇、DOM遅延レンダリングなどのエッジケースに対する防御ロジックを組み込みます。</li></ol><hr><h2 id="研究テーマ別の適用製品群マッピング" tabindex="-1">研究テーマ別の適用製品群マッピング <a class="header-anchor" href="#研究テーマ別の適用製品群マッピング" aria-label="Permalink to “研究テーマ別の適用製品群マッピング”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">研究ドキュメント</th><th style="text-align:left;">主要技術キーワード</th><th style="text-align:left;">商用適用製品群</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Playwright &amp; CDP同期</strong></td><td style="text-align:left;">CDP Frame Capture, Network Idle, Layout Shift</td><td style="text-align:left;"><code>SyncETA</code>, <code>SyncCrawl</code>, <code>sync-module-audit</code></td></tr><tr><td style="text-align:left;"><strong>Vision-LLM自己修復アルゴリズム</strong></td><td style="text-align:left;">バウンディングボックス推論, セマンティックDOMアンカー, Self-Healing</td><td style="text-align:left;"><code>SyncETA</code>, <code>SyncCrawl</code></td></tr><tr><td style="text-align:left;"><strong>MCP JSON-RPCオーケストレーション</strong></td><td style="text-align:left;">JSON-RPC 2.0, HTTP SSE, A2A Tool Discovery</td><td style="text-align:left;"><code>SyncVerse</code>, 全社11大エージェントMCPサーバー</td></tr><tr><td style="text-align:left;"><strong>仮想スレッド &amp; AgentScope</strong></td><td style="text-align:left;">JDK 25 Virtual Threads, <code>ReentrantLock</code>, <code>MsgHub</code></td><td style="text-align:left;"><code>sync-core</code>, <code>sync-module-ai</code>, 全社バックエンド</td></tr><tr><td style="text-align:left;"><strong>ハイブリッドRAG &amp; リランキング</strong></td><td style="text-align:left;"><code>PostgreSQL 18.6 pgvector</code> HNSW, <code>pg_trgm</code>, Cross-Encoder</td><td style="text-align:left;"><code>sync-module-rag</code>, <code>SyncInsight</code>, <code>SyncCrawl</code></td></tr><tr><td style="text-align:left;"><strong>Vision-LLMファインチューニング &amp; 劣化分析</strong></td><td style="text-align:left;">Llama-3.2-Vision, LoRA, Catastrophic Forgetting防止</td><td style="text-align:left;"><code>SyncETA</code>, <code>SyncLLM</code> オンプレミスモデル</td></tr></tbody></table>',17)])])}const p=e(l,[["render",n]]);export{y as __pageData,p as default};
